"use client";
import { useRouter } from "next/navigation";
import React from "react";
import Image from "next/image";
import { motion } from "framer-motion";

export default function HeroSection() {
  const router = useRouter();

  return (
    <section className="relative flex flex-col lg:flex-row items-center justify-between px-6 sm:px-10 lg:px-20 py-12 sm:py-20 bg-black text-white overflow-hidden min-h-screen">
      
      {/* ✅ Left Side - Text Content (Top on Mobile) */}
      <div className="flex flex-col items-center lg:items-start text-center lg:text-left w-full lg:w-2/3 z-20 order-1 lg:order-none pt-12">
        <motion.h1
          className="text-3xl sm:text-2xl md:text-3xl lg:text-4xl xl:text-5xl font-light leading-tight"
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1 }}
        >
          Accelerate <span className="text-white">AI Innovation.</span>
          <br className="hidden sm:block" />
          Build Smarter Intelligence.
          <br className="hidden sm:block" />
          Vetted Tech Talents.
        </motion.h1>

        <motion.p
          className="mt-4 sm:mt-6 text-sm sm:text-base md:text-lg lg:text-xl text-gray-400 max-w-md sm:max-w-lg lg:max-w-xl"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.5, duration: 1 }}
        >
          Train, fine-tune, and deploy next-generation AI models that redefine
          what’s possible.
        </motion.p>

        <motion.button
          className="mt-8 px-6 py-3 bg-white text-black font-semibold rounded-3xl shadow-lg hover:bg-gray-200 transition-all duration-200 text-sm sm:text-base"
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 1, duration: 0.8 }}
          onClick={() => router.push("/form")}
        >
          Get Started →
        </motion.button>
      </div>

      {/* ✅ Right Side - Image Section (Bottom on Mobile) */}
      <motion.div
        className="relative flex justify-center items-center w-full lg:w-1/3 mt-10 lg:mt-0 order-2 lg:order-none"
        initial={{ opacity: 0, x: 100 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ delay: 0.7, duration: 1.2 }}
      >
        <div className="bg-black p-[4px] sm:p-[6px] rounded-2xl w-full max-w-[500px] sm:max-w-[600px]">
          <Image
            src="/Generated Image October 31, 2025 - 6_39PM.webp"
            alt="AI Visualization"
            width={640}
            height={500}
            className="rounded-2xl w-full h-auto object-cover grayscale"
            priority
          />
        </div>
      </motion.div>

      {/* ✅ Subtle Gradient Overlay */}
      <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent pointer-events-none" />
    </section>
  );
}
